import sys

def main():
    s = sys.stdin.read().strip()
    if not s:
        print(0)
        return

    max_time = 0
    current_time = 0
    boys_before = 0

    for char in s:
        if char == 'M':
            boys_before += 1
        else:
            if boys_before > 0:
                if boys_before > current_time:
                    current_time += 1
                else:
                    current_time = boys_before
                if current_time > max_time:
                    max_time = current_time

    print(max_time)

if __name__ == "__main__":
    main()
